}

export function makeCar(kind, x, y, angle, color) {
  const palette = kind === 'sports' ? CAR_COLORS.sports : kind === 'police' ? CAR_COLORS.police : kind === 'taxi' ? CAR_COLORS.taxi : null;
  return {
    id: nextId,
