    }
    for (const ry of ROAD_Y) {
      if (ry < cam.y - 10 || ry > cam.y + VIEW.height + 10) continue;
      ctx.moveTo(Math.max(0, cam.x), ry);
      ctx.lineTo(Math.min(WORLD.width, cam.x + VIEW.width), ry);
    }
    ctx.stroke();
