    if (car.carKind === 'police') {
      ctx.fillStyle = Math.floor(G.time * 4) % 2 === 0 ? '#ff2e2e' : '#1e5cff';
      ctx.fillRect(-14, -9, 7, 5);
      ctx.fillStyle = Math.floor(G.time * 4) % 2 === 0 ? '#1e5cff' : '#ff2e2e';
      ctx.fillRect(-14, 4, 7, 5);
      ctx.fillStyle = '#0a0a0a';
