    drawBuildings(G);
    drawPalms(G);
    // Skid-free parked and traffic cars, then the living ones.
    for (const car of G.cars) {
      if (inView(G, car.x, car.y, 60)) drawCar(G, car);
    }
    for (const ped of G.peds) {
