    ctx.globalAlpha = 1;
    // The player, on foot or driving.
    const player = G.player;
    if (!player.inCar) {
      const blink = player.hurtFlash > 0 && Math.floor(player.hurtFlash * 12) % 2 === 0;
      if (!blink) {
        drawPerson(G, player.x, player.y, player.angle, PALETTE.player, player.radius, 'JAX');
